import React, { useState } from "react";

export function TabsControl({ tabs = ["overview", "analytics", "settings"] }: { tabs?: string[] }) {
  const [active, setActive] = useState(tabs[0]);
  return (
    <div className="flex items-center rounded-[8px] border border-border bg-muted/40 p-1 text-xs">
      {tabs.map((t) => (
        <button key={t} onClick={() => setActive(t)} className={`flex-1 py-1 rounded-[6px] capitalize ${active === t ? "bg-card text-foreground font-semibold shadow-sm" : "text-muted-foreground"}`}>{t}</button>
      ))}
    </div>
  );
}
